    "bio": {
      "by": "Родавы маёнтак сям'і Пілецкіх — Сукурчы пад Лідай, дзе ён пражыў значную частку жыцця, гаспадарыў і стварыў конны атрад. Добраахвотна трапіў у канцлагер Аўшвіц (Асвенцім), стварыў там падпольную сетку «Саюз вайсковых арганізацый» і склаў першыя ў свеце даклады пра Галакост («Справаздачы Пілецкага»). Удзельнік Варшаўскага паўстання 1944 г. Пасля вайны забіты камуністычным рэжымам у турме на Макатоўскай; сімвалічны мемарыял — у Пантэоне-маўзалеі на «Łączce» на Вайсковых могілках Павонзкі.",
      "ru": "Родовое имение семьи Пилецких находилось в Сукурчах под Лидой. Добровольно пошел узником в Освенцим для создания подполья и передал миру первые доклады об уничтожении узников. Расстрелян коммунистическим режимом в 1948 г.; кенотаф на участке «Łączka» Воинского кладбища Повонзки.",
      "en": "His family estate was in Sukurcze near Lida. Pilecki volunteered to be imprisoned in Auschwitz to organize resistance and gather intelligence, authoring the first comprehensive reports on the camp. Executed in 1948 by the communist regime; memorial at the 'Łączka' pantheon at Powązki Military Cemetery."
    },
